mapper.select:
SELECT id, user_id, key_name, key_prefix, key_hash, scope_bundle, status, last_used_at, created_at, updated_at, revoked_at
FROM user_api_key
WHERE id = #{id}

mapper.insert:
INSERT INTO user_api_key (
    user_id, key_name, key_prefix, key_hash, scope_bundle, status, last_used_at, created_at, updated_at, revoked_at
) VALUES (
    #{userId}, #{keyName}, #{keyPrefix}, #{keyHash}, #{scopeBundle}, #{status}, #{lastUsedAt}, NOW(), NOW(), #{revokedAt}
)

mapper.update:
UPDATE user_api_key
SET status = 'REVOKED',
    revoked_at = #{revokedAt},
    updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE user_api_key
SET last_used_at = #{lastUsedAt},
    updated_at = #{updatedAt}
WHERE id = #{id}
